<script setup>
import { computed, ref } from 'vue';
import { Head, Link, router } from '@inertiajs/vue3';
const props = defineProps({ organization: { type: Object, required: true }, currentBranch: { type: Object, required: true }, suppliers: { type: Object, required: true }, filters: { type: Object, required: true }, summary: { type: Object, required: true } });
const search = ref(props.filters.search ?? ''); const from = ref(props.filters.from ?? ''); const to = ref(props.filters.to ?? '');
const exportUrl = computed(() => { const q = new URLSearchParams(); if (search.value.trim()) q.set('search', search.value.trim()); if (from.value) q.set('from', from.value); if (to.value) q.set('to', to.value); return `/suppliers/performance/export${q.size ? `?${q}` : ''}`; });
const money = value => Number(value ?? 0).toLocaleString('ar-EG', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const supplierPurchaseChart = computed(() => [...(props.suppliers.data ?? [])].sort((a, b) => Number(b.totalPurchased ?? 0) - Number(a.totalPurchased ?? 0)).slice(0, 6));
const supplierChartMax = computed(() => Math.max(1, ...supplierPurchaseChart.value.map((supplier) => Number(supplier.totalPurchased ?? 0))));
function applyFilters() { router.get('/suppliers/performance', { search: search.value.trim() || undefined, from: from.value || undefined, to: to.value || undefined }, { preserveState: true, preserveScroll: true, replace: true }); }
function clearFilters() { search.value = ''; from.value = ''; to.value = ''; applyFilters(); }
</script>
<template>
  <Head title="أداء الموردين" />
  <main class="min-h-screen space-y-6 bg-slate-50 p-4 text-slate-900 sm:p-6" dir="rtl">
    <header class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-sm text-slate-500">{{ organization.name }} · {{ currentBranch.name }}</p><h1 class="mt-1 text-2xl font-bold">أداء الموردين</h1><p class="mt-1 text-sm text-slate-600">ملخص المشتريات والمرتجعات والمدفوعات والمبالغ المستحقة حسب الفرع والفترة.</p></div><div class="flex gap-2"><a :href="exportUrl" class="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold">تصدير CSV</a><Link href="/suppliers" class="rounded-lg bg-slate-900 px-4 py-2 text-sm font-semibold text-white">قائمة الموردين</Link></div></header>
    <section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><article v-for="card in [{label:'فواتير مستلمة',value:summary.invoiceCount,count:true},{label:'إجمالي المشتريات',value:summary.totalPurchased},{label:'مرتجعات المشتريات',value:summary.totalReturned},{label:'إجمالي المدفوع',value:summary.totalPaid},{label:'المستحق للموردين',value:summary.totalDue}]" :key="card.label" class="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><p class="text-sm text-slate-500">{{ card.label }}</p><p class="mt-2 text-xl font-bold tabular-nums">{{ card.count ? Number(card.value).toLocaleString('ar-EG') : money(card.value) }} <span v-if="!card.count" class="text-xs font-medium text-slate-500">{{ organization.currency }}</span></p></article></section>
    <section class="rounded-2xl border border-blue-100 bg-white p-5 shadow-sm sm:p-6">
      <div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-extrabold text-blue-700">مقارنة الموردين</p><h2 class="mt-1 text-lg font-black text-slate-900">أعلى الموردين حسب قيمة المشتريات</h2><p class="mt-1 text-sm text-slate-500">المخطط يعرض بيانات النتائج الظاهرة بعد تطبيق الفلاتر.</p></div><span class="rounded-xl bg-blue-50 px-3 py-2 text-xl">▥</span></div>
      <div v-if="supplierPurchaseChart.some((supplier) => Number(supplier.totalPurchased ?? 0) > 0)" class="mt-5 space-y-4">
        <div v-for="supplier in supplierPurchaseChart" :key="supplier.id" class="grid grid-cols-[minmax(85px,150px)_1fr_auto] items-center gap-3">
          <span class="truncate text-sm font-semibold text-slate-700" :title="supplier.name">{{ supplier.name }}</span>
          <div class="h-3 overflow-hidden rounded-full bg-slate-100"><div class="h-full rounded-full bg-gradient-to-l from-blue-600 to-sky-400 transition-all duration-500" :style="{ width: `${Math.max(2, Number(supplier.totalPurchased ?? 0) / supplierChartMax * 100)}%` }"></div></div>
          <span class="text-xs font-bold tabular-nums text-slate-700">{{ money(supplier.totalPurchased) }}</span>
        </div>
      </div>
      <p v-else class="mt-5 rounded-xl bg-slate-50 px-4 py-5 text-center text-sm text-slate-500">لا توجد مشتريات مسجلة لرسمها ضمن النتائج الحالية.</p>
    </section>
    <form class="grid gap-3 rounded-xl border border-slate-200 bg-white p-4 sm:grid-cols-2 xl:grid-cols-4" @submit.prevent="applyFilters"><label class="text-sm font-medium">بحث المورد<input v-model="search" type="search" placeholder="الاسم أو الكود أو الهاتف" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 font-normal" /></label><label class="text-sm font-medium">من تاريخ<input v-model="from" type="date" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 font-normal" /></label><label class="text-sm font-medium">إلى تاريخ<input v-model="to" type="date" :min="from || undefined" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 font-normal" /></label><div class="flex items-end gap-2"><button class="rounded-lg bg-slate-900 px-4 py-2 font-semibold text-white">تطبيق</button><button type="button" class="rounded-lg border border-slate-300 px-4 py-2" @click="clearFilters">مسح</button></div></form>
    <section class="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><div class="overflow-x-auto"><table class="min-w-[950px] w-full text-right text-sm"><thead class="bg-slate-100 text-slate-600"><tr><th class="p-3">المورد</th><th class="p-3">عدد الفواتير</th><th class="p-3">المشتريات</th><th class="p-3">المرتجعات</th><th class="p-3">المدفوع</th><th class="p-3">المستحق</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="supplier in suppliers.data" :key="supplier.id" class="hover:bg-slate-50"><td class="p-3"><div class="font-semibold">{{ supplier.name }}</div><div class="mt-1 text-xs text-slate-500">{{ supplier.code || '—' }} · {{ supplier.phone || 'بدون هاتف' }}</div></td><td class="p-3 tabular-nums">{{ supplier.invoiceCount }}</td><td class="p-3 tabular-nums">{{ money(supplier.totalPurchased) }}</td><td class="p-3 tabular-nums">{{ money(supplier.totalReturned) }}</td><td class="p-3 tabular-nums">{{ money(supplier.totalPaid) }}</td><td class="p-3 font-bold tabular-nums" :class="Number(supplier.totalDue)>0?'text-amber-700':'text-emerald-700'">{{ money(supplier.totalDue) }}</td></tr><tr v-if="!suppliers.data?.length"><td colspan="6" class="p-8 text-center text-slate-500">لا توجد فواتير مشتريات مستلمة ضمن الفلاتر المحددة.</td></tr></tbody></table></div><footer v-if="suppliers.links?.length>3" class="flex flex-wrap gap-2 border-t border-slate-100 p-3"><template v-for="link in suppliers.links" :key="`${link.label}-${link.url}`"><Link v-if="link.url" :href="link.url" preserve-scroll class="rounded-lg border px-3 py-2 text-sm" :class="link.active?'border-slate-900 bg-slate-900 text-white':'border-slate-200 bg-white'" v-html="link.label"/><span v-else class="rounded-lg border border-slate-100 px-3 py-2 text-sm text-slate-400" v-html="link.label"/></template></footer></section>
  </main>
</template>
